namespace QualityReporter.CSharp.Analysis;
public static class RiskCalculator { public static void Calculate(List<FileResult> files,RiskWeights w) { Set(files,x=>x.History.CommitCount,(r,p)=>r.ChangePercentile=p);Set(files,x=>x.History.Churn,(r,p)=>r.ChurnPercentile=p);Set(files,x=>x.History.ReworkRate,(r,p)=>r.ReworkPercentile=p);Set(files,x=>x.Metrics.Complexity,(r,p)=>r.ComplexityPercentile=p);Set(files,x=>x.Metrics.Issues.Error+x.Metrics.Issues.Warning+x.Metrics.Issues.Info,(r,p)=>r.IssuePercentile=p);var covered=files.Where(x=>x.Metrics.LineCoverage.HasValue).ToList();Set(covered,x=>-x.Metrics.LineCoverage!.Value,(r,p)=>r.CoverageRiskPercentile=p);foreach(var f in files){var terms=new[]{(f.Risk.ChangePercentile,w.Change),(f.Risk.ChurnPercentile,w.Churn),(f.Risk.ReworkPercentile,w.Rework),(f.Risk.ComplexityPercentile,w.Complexity),(f.Risk.CoverageRiskPercentile,w.Coverage),(f.Risk.IssuePercentile,w.Issues)}.Where(x=>x.Item1.HasValue&&x.Item2>0).ToList();f.Risk.Score=Math.Round(terms.Sum(x=>x.Item1!.Value*x.Item2)/terms.Sum(x=>x.Item2)*100,1);f.Risk.Level=f.Risk.Score>=80?"critical":f.Risk.Score>=60?"high":f.Risk.Score>=40?"medium":"low";} }
 static void Set<T>(List<FileResult> fs,Func<FileResult,T> value,Action<Risk,double> set) where T:IComparable<T>{var sorted=fs.Select(value).Order().ToList();var allEqual=sorted.Count<2||sorted[0].CompareTo(sorted[^1])==0;foreach(var f in fs){var v=value(f);var below=sorted.Count(x=>x.CompareTo(v)<0);var equal=sorted.Count(x=>x.CompareTo(v)==0);set(f.Risk,allEqual?0:(below+(equal-1)/2d)/(sorted.Count-1));}}
}
public static class BaselineComparer { public static object Compare(Report current,Report old){var now=current.Files.ToDictionary(x=>x.Path);var before=old.Files.ToDictionary(x=>x.Path);return new { newHotspots=now.Values.Where(x=>x.Risk.Score>=60&&(!before.TryGetValue(x.Path,out var b)||b.Risk.Score<60)).Select(x=>x.Path),resolvedHotspots=before.Values.Where(x=>x.Risk.Score>=60&&(!now.TryGetValue(x.Path,out var n)||n.Risk.Score<60)).Select(x=>x.Path),riskIncreased=now.Values.Where(x=>before.TryGetValue(x.Path,out var b)&&x.Risk.Score>b.Risk.Score).Select(x=>x.Path),riskDecreased=now.Values.Where(x=>before.TryGetValue(x.Path,out var b)&&x.Risk.Score<b.Risk.Score).Select(x=>x.Path)};}}
